33	class ScatterTester extends Module {
34	  val io = IO(new Bundle {
35	    val indicesValid = Input(Vec(16, Bool()))
36	    val indices = Input(Vec(16, UInt(4.W)))
37	    val data = Input(Vec(16, UInt(8.W)))
38	
39	    val indicesSelected = Output(Vec(16, Bool()))
40	    val writeMask = Output(Vec(16, Bool()))
41	    val outData = Output(Vec(16, UInt(8.W)))
42	
43	    val maskCount = Output(UInt(5.W))
44	  })
45	
46	  val (result, writeMask, indicesSelected) = Scatter(
47	      io.indicesValid, io.indices, io.data)
48	
49	  io.indicesSelected := indicesSelected
50	  io.writeMask := writeMask
51	  io.outData := result
52	  io.maskCount := PopCount(writeMask)
53	}
54	
55	class GatherSpec extends AnyFreeSpec with ChiselSim {
56	  "Random Test" in {
57	    simulate(new GatherTester) { dut =>
58	      for (_ <- 0 until 100) {
59	        // Set inputs
60	        val indices = Seq.fill(16)(Random.between(0, 16))
61	        val data = Seq.fill(16)(Random.between(0, 256))
62	        for (i <- 0 until 16) {
63	          dut.io.indices(i).poke(indices(i))
64	          dut.io.data(i).poke(data(i))
65	        }
66	
67	        // Check results
68	        for (i <- 0 until 16) {
69	          dut.io.out(i).expect(data(indices(i)))
70	        }
71	      }
72	    }
73	  }
74	}
