22	trait IndexAllocatorSpec extends ChiselSim { this: AnyFreeSpec =>
23	  def makeDut(): IndexAllocator
24	
25	  def spec(capacity: Int) = {
26	    "Initialize" in {
27	      simulate(makeDut()) {dut =>
28	        dut.io.alloc.valid.expect(true.B)
29	        dut.io.alloc.bits.expect(0.U)
30	        dut.io.free.ready.expect(false.B)
31	      }
32	    }
33	
34	    "Allocate all" in {
35	      simulate(makeDut()) {dut =>
36	        dut.io.alloc.ready.poke(true.B)
37	        for (i <- (0 until capacity)) {
38	          dut.io.alloc.valid.expect(true.B)
39	          dut.io.alloc.bits.expect(i.U)
40	          dut.clock.step()
41	        }
42	        dut.io.alloc.valid.expect(false.B)
43	      }
44	    }
45	
46	    "No pipe" in {
47	      simulate(makeDut()) {dut =>
48	        dut.io.alloc.ready.poke(true.B)
49	        dut.io.free.ready.expect(false.B)
50	      }
51	    }
52	
53	    "Flow" in {
54	      simulate(makeDut()) {dut =>
55	        dut.io.alloc.ready.poke(true.B)
56	        for (i <- (0 until capacity)) {
57	          dut.clock.step()
58	        }
59	        dut.io.free.valid.poke(true.B)
60	        dut.io.free.bits.poke(1.U)
61	        dut.io.alloc.valid.expect(true.B)
62	        dut.io.alloc.bits.expect(1.U)
63	      }
64	    }
65	
66	    "Out of order free" in {
67	      simulate(makeDut()) {dut =>
68	        dut.io.alloc.ready.poke(true.B)
69	        for (i <- (0 until capacity)) {
70	          dut.clock.step()
71	        }
72	        dut.io.alloc.ready.poke(false.B)
73	        dut.io.free.valid.poke(true.B)
74	        val s = Random.shuffle((0 until capacity).toVector)
75	        for (i <- s) {
76	          dut.io.free.bits.poke(i.U)
77	          dut.clock.step()
78	        }
79	        // Dump all Index for inspection
80	        dut.io.alloc.ready.poke(true.B)
81	        dut.io.free.valid.poke(false.B)
82	        for (i <- s) {
83	          dut.io.alloc.valid.expect(true.B)
84	          dut.io.alloc.bits.expect(i.U)
85	          dut.clock.step()
86	        }
87	      }
88	    }
89	
90	    "Alloc and free on same cycle" in {
91	      simulate(makeDut()) {dut =>
92	        dut.io.alloc.ready.poke(true.B)
93	        dut.clock.step()
94	        // We allocated 0
95	        // Now we allocate 1 and free 0
96	        dut.io.free.valid.poke(true.B)
97	        dut.io.free.bits.poke(0.U)
98	        dut.clock.step()
99	        // Dump all Index for inspection
100	        dut.io.free.valid.poke(false.B)
101	        val s = 0 +: (2 until capacity).toVector
102	        for (i <- s) {
103	          dut.io.alloc.valid.expect(true.B)
104	          dut.io.alloc.bits.expect(i.U)
105	          dut.clock.step()
106	        }
107	      }
108	    }
109	  }
110	}
