36	ABSL_FLAG(int, cycles, 100000000, "Simulation cycles");
37	ABSL_FLAG(bool, trace, false, "Dump VCD trace");
38	ABSL_FLAG(std::string, binary, "", "Binary to execute");
39	ABSL_FLAG(bool, debug_axi, false, "Enable AXI traffic debugging");
40	ABSL_FLAG(bool, instr_trace, false, "Log instructions to console");
41	ABSL_FLAG(bool, backdoor_load, false, "Enable high-speed backdoor code loading");
