43	static bool run(const char* name, const std::string binary, const int cycles,
44	                const bool trace, const bool debug_axi, const bool instr_trace,
45	                const bool backdoor_load) {
46	  absl::Mutex halted_mtx;
47	  absl::CondVar halted_cv;
48	  CoreMiniAxi_tb tb(CoreMiniAxi_tb::kCoreMiniAxiModelName, cycles, /* random= */ false, debug_axi,
49	                    instr_trace, backdoor_load,
50	                    /*wfi_cb=*/std::nullopt,
51	                    /*halted_cb=*/[&halted_mtx, &halted_cv]() {
52	                      absl::MutexLock lock_(&halted_mtx);
53	                      halted_cv.SignalAll();
54	                    });
55	  // Ensure we call sc_start @0 time, before we startup anything else.
56	  // This allows Verilog `initial` blocks to run before we try to interact with the
57	  // DUT model.
58	  sc_start(SC_ZERO_TIME);
59	
60	  if (trace) {
61	    tb.trace(tb.core());
62	  }
63	
64	  std::thread sc_main_thread([&tb]() { tb.start(); });
65	
66	  CHECK_OK(tb.LoadElfSync(binary));
67	  CHECK_OK(tb.ClockGateSync(false));
68	  CHECK_OK(tb.ResetAsync(false));
69	
70	  {
71	    absl::MutexLock lock_(&halted_mtx);
72	    halted_cv.Wait(&halted_mtx);
73	  }
74	
75	  if (!tb.io_fault && !tb.tohost_halt) {
76	    CHECK_OK(tb.CheckStatusSync());
77	  }
78	
79	  sc_stop();
80	  sc_main_thread.join();
81	  return (!tb.io_fault && !(tb.tohost_halt && tb.tohost_val != 1));
82	}
