84	extern "C" int sc_main(int argc, char** argv) {
85	  absl::InitializeLog();
86	  absl::SetProgramUsageMessage("CoreMiniAxi simulator");
87	  auto args = absl::ParseCommandLine(argc, argv);
88	
89	  // Pass clean arguments to Verilator.
90	  int v_argc = args.size();
91	  char** v_argv = &args[0];
92	  Verilated::commandArgs(v_argc, v_argv);
93	
94	  if (absl::GetFlag(FLAGS_binary) == "") {
95	    LOG(ERROR) << "--binary is required!";
96	    return -1;
97	  }
98	
99	  return run(Sysc_tb::get_name(argv[0]), absl::GetFlag(FLAGS_binary),
100	      absl::GetFlag(FLAGS_cycles), absl::GetFlag(FLAGS_trace),
101	      absl::GetFlag(FLAGS_debug_axi), absl::GetFlag(FLAGS_instr_trace),
102	      absl::GetFlag(FLAGS_backdoor_load)) ? 0 : 1;
103	}
