102	// Base class for testbench {posedge & negedge}.
103	struct Sysc_tb : public sc_module {
104	  sc_clock clock;
105	  sc_signal<bool> reset;
106	  sc_signal<bool> resetn;
107	
108	  SC_HAS_PROCESS(Sysc_tb);
109	
110	  Sysc_tb(sc_module_name n, int loops, bool random = true)
111	      : sc_module(n),
112	        clock("clock", 1, SC_NS),
113	        reset("reset"),
114	        resetn("resetn"),
115	        random_(random),
116	        loops_(loops) {
117	    loop_ = 0;
118	    error_ = false;
119	
120	    SC_METHOD(tb_posedge);
121	    sensitive << clock_.pos();
122	
123	    SC_METHOD(tb_negedge);
124	    sensitive << clock_.neg();
125	
126	    SC_METHOD(tb_stop);
127	    sensitive << clock_.neg();
128	
129	    clock_(clock);
130	
131	    // Verilated::commandArgs(argc, argv);
132	    tf_ = new VerilatedFstC;
133	  }
134	
135	  ~Sysc_tb() {
136	    if (tf_) {
137	      tf_->dump(sim_time_);  // last falling edge
138	      tf_->close();
139	      delete tf_;
140	      tf_ = nullptr;
141	    }
142	    if (error_) {
143	      exit(23);
144	    }
145	  }
146	
147	  void start() {
148	    init();
149	
150	    reset = 1;
151	    resetn = 0;
152	    sc_start(4.75, SC_NS);  // falling edge of clock
153	    reset = 0;
154	    resetn = 1;
155	
156	    started_ = true;
157	    sc_start();
158	
159	    if (tf_) {
160	      tf_->dump(sim_time_++);  // last falling edge
161	      tf_->close();
162	      delete tf_;
163	      tf_ = nullptr;
164	    }
165	  }
166	
167	  template <typename T>
168	  void trace(T* design, const char *name = "") {
169	    if (!strlen(name)) {
170	      name = design->name();
171	    }
172	    std::string path = std::string("/tmp/") + name;
173	
174	    reset = 1;
175	    resetn = 0;
176	    sc_start(SC_ZERO_TIME);
177	    reset = 0;
178	    resetn = 1;
179	
180	    design->trace(tf_, 99);
181	    path += ".fst";
182	    Verilated::traceEverOn(true);
183	    tf_->open(path.c_str());
184	    printf("\nInfo: default timescale unit used for tracing: 1 ps (%s)\n",
185	           path.c_str());
186	  }
187	
188	  static char *get_name(char *s) {
189	    const int len = strlen(s);
190	    char *p = s;
191	    for (int i = 0; i < len; ++i) {
192	      if (s[i] == '/') {
193	        p = s + i + 1;
194	      }
195	    }
196	    return p;
197	  }
198	
199	 protected:
200	  virtual void init() {}
201	  virtual void posedge() {}
202	  virtual void negedge() {}
203	
204	  bool check(bool v, const char *s = "") {
205	    const char *KRED = "\x1B[31m";
206	    const char *KRST = "\033[0m";
207	    if (!v) {
208	      sc_stop();
209	      printf("%s", KRED);
210	      if (strlen(s)) {
211	        printf("***ERROR[%s]::VERIFY \"%s\"\n", this->name(), s);
212	      } else {
213	        printf("***ERROR[%s]::VERIFY\n", this->name());
214	      }
215	      printf("%s", KRST);
216	      error_ = true;
217	    }
218	    return v;
219	  }
220	
221	  bool rand_bool() {
222	    // Do not allow any 'io_in_valid' controls to be set during reset.
223	    return !reset &&
224	           (!random_ || (rand() & 1));  // NOLINT(runtime/threadsafe_fn)
225	  }
226	
227	  // Generates a number on the range [min, max].
228	  int rand_int(int min = 0, int max = (1 << 31)) {
229	    return (rand() % (max - min + 1)) + min;  // NOLINT(runtime/threadsafe_fn)
230	  }
231	
232	  uint32_t rand_uint32(uint32_t min = 0, uint32_t max = 0xffffffffu) {
233	    uint32_t r = (rand() & 0xffff) |  // NOLINT(runtime/threadsafe_fn)
234	                 (rand() << 16);      // NOLINT(runtime/threadsafe_fn)
235	    if (min == 0 && max == 0xffffffff) return r;
236	    return (r % (max - min + 1)) + min;
237	  }
238	
239	  uint64_t rand_uint64(uint64_t min = 0, uint64_t max = 0xffffffffffffffffull) {
240	    uint64_t r = rand_uint32() | (uint64_t(rand_uint32()) << 32);
241	    if (min == 0 && max == 0xffffffffffffffffull) return r;
242	    return (r % (max - min + 1)) + min;
243	  }
244	
245	  uint32_t cycle() {
246	    return sim_time_ / 2;  // posedge + negedge
247	  }
248	
249	 private:
250	  const bool random_;
251	  const int loops_;
252	  int loop_;
253	  bool error_;
254	  bool started_;
255	
256	  sc_in<bool> clock_;
257	
258	  uint32_t sim_time_ = 0;
259	  VerilatedFstC *tf_ = nullptr;
260	
261	  void tb_posedge() {
262	    if (tf_ && started_) { tf_->dump(sim_time_++); tf_->flush(); }
263	    if (reset) return;
264	    posedge();
265	  }
266	
267	  void tb_negedge() {
268	    if (tf_ && started_) { tf_->dump(sim_time_++); tf_->flush(); }
269	    if (reset) return;
270	    negedge();
271	  }
272	
273	  void tb_stop() {
274	    // LessThanEqual for one more edge (end - start + 1).
275	    if (loop_ <= loops_) {
276	      loop_++;
277	    } else {
278	      printf("\nInfo: loop limit \"%d\" reached\n", loops_);
279	      sc_stop();
280	    }
281	  }
282	};
