45	struct Core_if : Memory_if {
46	  sc_in<bool>         io_ibus_valid;
47	  sc_out<bool>        io_ibus_ready;
48	  sc_in<sc_bv<32> >   io_ibus_addr;
49	  sc_out<sc_bv<KP_fetchDataBits> > io_ibus_rdata;
50	
51	  sc_out<bool> io_ibus_fault_valid;
52	  sc_out<bool> io_ibus_fault_bits_write;
53	  sc_out<sc_bv<32>> io_ibus_fault_bits_addr;
54	  sc_out<sc_bv<32>> io_ibus_fault_bits_epc;
55	
56	  sc_in<bool> io_dbus_valid;
57	  sc_out<bool> io_dbus_ready;
58	  sc_in<bool> io_dbus_write;
59	  sc_in<sc_bv<32> > io_dbus_addr;
60	  sc_in<sc_bv<32> > io_dbus_adrx;
61	  sc_in<sc_bv<KP_dbusSize> > io_dbus_size;
62	  sc_in<sc_bv<KP_lsuDataBits> > io_dbus_wdata;
63	  sc_in<sc_bv<KP_lsuDataBits / 8> > io_dbus_wmask;
64	  sc_out<sc_bv<KP_lsuDataBits> > io_dbus_rdata;
65	
66	  Core_if(sc_module_name n, const char* bin) : Memory_if(n, bin) {
67	    for (int i = 0; i < KP_lsuDataBits / 32; ++i) {
68	      runused_.set_word(i, 0);
69	    }
70	  }
71	
72	  void eval() {
73	    if (reset) {
74	      io_ibus_ready = false;
75	    } else if (clock->posedge()) {
76	      cycle_++;
77	
78	      io_ibus_ready = rand_bool_ibus();
79	      io_dbus_ready = rand_bool_dbus();
80	
81	      // Instruction bus read.
82	      if (io_ibus_valid && io_ibus_ready) {
83	        sc_bv<256> rdata;
84	        uint32_t addr = io_ibus_addr.read().get_word(0);
85	        uint32_t words[256 / 32];
86	        if (Read(addr, 256 / 8, reinterpret_cast<uint8_t*>(words))) {
87	          for (int i = 0; i < 256 / 32; ++i) {
88	            rdata.set_word(i, words[i]);
89	          }
90	
91	          io_ibus_rdata = rdata;
92	        } else {
93	          io_ibus_fault_valid = true;
94	          io_ibus_fault_bits_write = false;
95	          io_ibus_fault_bits_addr = 0;
96	          io_ibus_fault_bits_epc = addr;
97	        }
98	      } else {
99	       io_ibus_fault_valid = false;
100	      }
101	
102	      // Data bus read.
103	      if (io_dbus_valid && io_dbus_ready && !io_dbus_write) {
104	        sc_bv<KP_lsuDataBits> rdata;
105	        uint32_t addr = io_dbus_addr.read().get_word(0);
106	        uint32_t words[KP_lsuDataBits / 32] = {0};
107	        memset(words, 0xcc, sizeof(words));
108	        int bytes = io_dbus_size.read().get_word(0);
109	        if (Read(addr, bytes, reinterpret_cast<uint8_t*>(words))) {
110	          ReadSwizzle(addr, KP_lsuDataBits / 8, reinterpret_cast<uint8_t*>(words));
111	          for (int i = 0; i < KP_lsuDataBits / 32; ++i) {
112	            rdata.set_word(i, words[i]);
113	          }
114	          io_dbus_rdata = rdata;
115	        } else {
116	          assert(false);
117	        }
118	      }
119	
120	      // Data bus write.
121	      if (io_dbus_valid && io_dbus_ready && io_dbus_write) {
122	        sc_bv<KP_lsuDataBits> wdata = io_dbus_wdata;
123	        uint32_t addr = io_dbus_addr.read().get_word(0);
124	        uint32_t words[KP_lsuDataBits / 32];
125	        int bytes = io_dbus_size.read().get_word(0);
126	        for (int i = 0; i < KP_lsuDataBits / 32; ++i) {
127	          words[i] = wdata.get_word(i);
128	        }
129	        WriteSwizzle(addr, KP_lsuDataBits / 8, reinterpret_cast<uint8_t*>(words));
130	        if (!Write(addr, bytes, reinterpret_cast<uint8_t*>(words))) {
131	          assert(false);
132	        }
133	      }
134	
135	      rtcm_t tcm_read;
136	      sc_bv<KP_lsuDataBits> rdata;
137	    }
138	  }
