140	 private:
141	  uint32_t cycle_ = 0;
142	
143	  struct rtcm_t {
144	    uint32_t cycle;
145	    uint32_t id : 7;
146	    sc_bv<KP_lsuDataBits> data;
147	  };
148	
149	  fifo_t<rtcm_t> rtcm_[2];
150	  sc_bv<KP_lsuDataBits> runused_;
151	};
